-- JuntApp MVP: run this migration in a Supabase project after enabling Google OAuth.
create extension if not exists "pgcrypto";

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now());
create table public.groups (id uuid primary key default gen_random_uuid(), name text not null check (char_length(trim(name)) > 0), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.group_members (group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role text not null check(role in ('owner','member')), joined_at timestamptz not null default now(), primary key(group_id,user_id));
create table public.group_invites (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, token text not null unique default encode(gen_random_bytes(18),'hex'), created_by uuid not null references public.profiles(id), expires_at timestamptz, max_uses integer check(max_uses is null or max_uses > 0), uses_count integer not null default 0 check(uses_count >= 0), created_at timestamptz not null default now());
create table public.plans (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, title text not null check(char_length(trim(title)) > 0), description text, scheduled_at timestamptz not null, status text not null default 'voting' check(status in ('voting','confirmed','completed','cancelled')), selected_option_id uuid, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.plan_options (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.plans(id) on delete cascade, title text not null, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
alter table public.plans add constraint plans_selected_option_fk foreign key(selected_option_id) references public.plan_options(id) on delete set null;
create table public.votes (option_id uuid not null references public.plan_options(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(option_id,user_id));
create table public.plan_participants (plan_id uuid not null references public.plans(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, attendance_status text not null check(attendance_status in ('going','maybe','not_going')), updated_at timestamptz not null default now(), primary key(plan_id,user_id));
create table public.saved_locations (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, label text not null, address_text text, latitude numeric, longitude numeric, created_at timestamptz not null default now());
create table public.plan_origins (plan_id uuid not null references public.plans(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, source_type text not null check(source_type in ('saved_location','current_location','custom_location')), saved_location_id uuid references public.saved_locations(id) on delete set null, latitude numeric, longitude numeric, updated_at timestamptz not null default now(), primary key(plan_id,user_id));

create or replace function public.is_group_member(target_group uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.group_members where group_id=target_group and user_id=auth.uid()) $$;
alter table public.profiles enable row level security; alter table public.groups enable row level security; alter table public.group_members enable row level security; alter table public.group_invites enable row level security; alter table public.plans enable row level security; alter table public.plan_options enable row level security; alter table public.votes enable row level security; alter table public.plan_participants enable row level security; alter table public.saved_locations enable row level security; alter table public.plan_origins enable row level security;
create policy "profile is private" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "members read groups" on public.groups for select using(public.is_group_member(id)); create policy "users create groups" on public.groups for insert with check(created_by=auth.uid());
create policy "members read membership" on public.group_members for select using(public.is_group_member(group_id)); create policy "group creator adds owner" on public.group_members for insert with check(user_id=auth.uid());
create policy "members read plans" on public.plans for select using(public.is_group_member(group_id)); create policy "members create plans" on public.plans for insert with check(public.is_group_member(group_id) and created_by=auth.uid());
create policy "members read options" on public.plan_options for select using(exists(select 1 from public.plans p where p.id=plan_id and public.is_group_member(p.group_id))); create policy "members create options" on public.plan_options for insert with check(exists(select 1 from public.plans p where p.id=plan_id and public.is_group_member(p.group_id)));
create policy "members read votes" on public.votes for select using(exists(select 1 from public.plan_options o join public.plans p on p.id=o.plan_id where o.id=option_id and public.is_group_member(p.group_id))); create policy "member manages own votes" on public.votes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "members read attendance" on public.plan_participants for select using(exists(select 1 from public.plans p where p.id=plan_id and public.is_group_member(p.group_id))); create policy "member manages attendance" on public.plan_participants for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "locations private" on public.saved_locations for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "origins private" on public.plan_origins for all using(user_id=auth.uid()) with check(user_id=auth.uid());
